import{z as B,x as l,o,c as d,q as A,j as n,D as t,d as e,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Tiebout 用脚投票","description":"","frontmatter":{"title":"Tiebout 用脚投票","date":"2026-09-27T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/tiebout-sorting.md","filePath":"econ/tiebout-sorting.md","lastUpdated":1791063341000}'),p={name:"econ/tiebout-sorting.md"};function C(u,E,D,m,b,c){const i=l("Mermaid");return o(),d("div",null,[E[2]||(E[2]=A('<h1 id="tiebout-用脚投票" tabindex="-1">Tiebout 用脚投票 <a class="header-anchor" href="#tiebout-用脚投票" aria-label="Permalink to &quot;Tiebout 用脚投票&quot;">​</a></h1><div class="epigraph"><p>公共品不用投票也能「定价」：居民挑社区落脚，偏好被脚投票显式披露，地方竞争把萨缪尔森难题松了一扣。</p><footer>—— 据 Tiebout「A Pure Theory of Local Expenditures」(1956)；Oates 财政联邦主义 (1972)</footer></div><p>萨缪尔森 (1954) 断言公共品偏好在投票中无法被真实披露——人人隐藏口味搭便车。Tiebout 的回应：把「买不买」换成「搬不搬」。缺口是<strong>辖区竞争模型</strong>：多辖区、差异化税包，居民迁移使偏好显形。本课只做流动性红利一侧，不做辖区间恶性减税竞争的另一面。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全国性公共品无法用脚投票，地方性公共品（学校、治安、绿化）可以。若辖区数量足够、迁移无成本、居民完全信息，每人选出「税收-服务包」最合身的社区——市场机制在公共品上的复现。要问的是：这个复现在哪些假设下成立，偏离时谁受损？</p><p><span class="marginnote">术语翻译：用脚投票（voting with feet）= 以迁移代替投票披露偏好；税收-服务包（tax-service package）= 辖区同时给出的税率与公共品组合，类比商品的价格-质量组合。</span></p><p><span class="marginnote">数字实例：两个辖区，学区质量高低之别，房产税差 1.5%。高偏好家庭愿意为优质学区付房价溢价——资本化研究显示边境学区房价差可达 15–25%，远高于税差本身：税付一次性，服务吃很多年。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型骨架：\\(N\\) 个辖区各供一档公共品 \\(g_j\\) 与人头税 \\(t_j\\)；居民 \\(i\\) 效用 \\(u(x_i, g_j)-t_j\\)，选使效用最大的辖区；辖区在给定人口下以最低成本供 \\(g\\)。均衡时每个居民落在最优包上，且各辖区成本最小——<strong>偏好被分拣（sorting）而不是被披露</strong>。Oates 加上对应性原则：收益归属哪级辖区，就由哪级征税。</p>',9)),(o(),n(s,null,{default:t(()=>[r(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%A4%9A%E8%BE%96%E5%8C%BA%3A%20%E5%90%84%E6%9C%89%E7%A8%8E-%E6%9C%8D%E5%8A%A1%E5%8C%85%22%5D%20--%3E%20B%5B%22%E5%B1%85%E6%B0%91%E6%AF%94%E8%BE%83%E6%95%88%E7%94%A8%22%5D%0A%20%20B%20--%3E%20C%7B%22%E6%90%AC%3F%22%7D%0A%20%20C%20--%3E%7C%22%E8%BF%81%E5%85%A5%22%7C%20D%5B%22%E8%BE%96%E5%8C%BA%E4%BA%BA%E5%8F%A3%E5%8F%98%E5%8C%96%22%5D%0A%20%20C%20--%3E%7C%22%E7%95%99%22%7C%20E%5B%22%E5%9D%87%E8%A1%A1%E6%A0%B8%E9%AA%8C%22%5D%0A%20%20D%20--%3E%20F%5B%22%E6%88%90%E6%9C%AC%2F%E7%A8%8E%E5%9F%BA%E9%87%8D%E6%8E%92%22%5D%0A%20%20F%20--%3E%20B%0A%20%20E%20--%3E%20G%5B%22%E5%9D%87%E8%A1%A1%3A%20%E4%BA%BA%E4%BA%BA%E8%90%BD%E5%9C%A8%E6%9C%80%E4%BC%98%E5%8C%85%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：把辖区想成自助餐厅的档口——不用举手表决全楼吃什么，各取所需即可；前提是你换档口不要排队成本，且每档口的成本只跟自家食客人数有关。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("Tiebout 均衡的效率来源是"),a("strong",null,"拥挤性公共品的准私有化"),e("：当 \\(g_j\\) 的边际成本随人口线性上升，人头税恰好把它「内部化」，居民迁移至边际收益等于边际税收处，条件与私人品市场出清同构。 Hamilton (1975) 补上房产税版本：以最低住房消费作为分区门槛，把辖区变成「俱乐部」，资本化让门槛自我执行。但效率有三个暗桩——辖区间外部性（治污外溢）、再分配失灵（穷人被挤出好学区）、以及土地开发商操纵供给。")],-1)),(o(),n(s,null,{default:t(()=>[r(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%95%88%E7%8E%87%E6%88%90%E7%AB%8B%E9%9D%A0%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%7C%22%E6%8B%A5%E6%8C%A4%E6%88%90%E6%9C%AC%E5%86%85%E9%83%A8%E5%8C%96%22%7C%20R%5B%22%E4%BA%BA%E5%A4%B4%E7%A8%8E%3D%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B5%84%E6%9C%AC%E5%8C%96%E9%97%A8%E6%A7%9B%22%7C%20S%5B%22%E6%88%BF%E4%BB%B7%E5%8F%8D%E6%98%A0%E5%87%80%E6%9C%8D%E5%8A%A1%E4%BB%B7%E5%80%BC%22%5D%0A%20%20R%20--%3E%20T%5B%22%E5%B8%82%E5%9C%BA%E5%90%8C%E6%9E%84%E8%BE%BE%E6%88%90%22%5D%0A%20%20S%20--%3E%20T%0A%20%20U%7B%22%E4%B8%89%E4%B8%AA%E6%9A%97%E6%A1%A9%22%7D%20--%3E%20V%5B%22%E5%A4%96%E9%83%A8%E6%80%A7%E5%A4%96%E6%BA%A2%22%5D%0A%20%20U%20--%3E%20W%5B%22%E5%86%8D%E5%88%86%E9%85%8D%E5%A4%B1%E7%81%B5%22%5D%0A%20%20U%20--%3E%20X%5B%22%E5%9C%9F%E5%9C%B0%E4%BE%9B%E7%BB%99%E6%93%8D%E7%BA%B5%22%5D%0A%20%20V%20--%3E%20Y%5B%22%E5%9D%87%E8%A1%A1%E5%81%8F%E7%A6%BB%E6%9C%80%E4%BC%98%22%5D%0A%20%20W%20--%3E%20Y%0A%20%20X%20--%3E%20Y%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">常见误区：把 Tiebout 当成「地方竞争必然有效」——模型假设迁移无成本、就业外生；现实里双职工家庭迁移成本高达数年收入，而辖区为抢税基压低税率会切断「税收=边际成本」的等式，效率论证反转为逐底论证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>实证检验走资本化路线：Oates (1969) 的房产税-学区价值回归开启五十年文献，现代断点设计利用辖区边界确认溢价。适用边界：服务同质、人口可分、辖区较多的都会区最像模型；农村与单一城市内部不适用。政策接口：财政转移支付要补偿「搭便车的邻居」，学区择校的公平性争论本质是 Tiebout 效率与 Rawls 分配的对撞。与<a href="/econ/congestion-pricing">拥堵定价</a>衔接：同一「按使用付费」逻辑从空间维度转向时间维度。</p><p><span class="marginnote">直觉类比：Tiebout 世界像自助餐再进一步——每家餐厅只做一道菜且成本随人数线性，食客流动自动校准价格；一旦某餐厅的菜香飘到隔壁（外部性）或菜单给熟客打折（再分配），市场同构就漏气。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>偏好靠分拣披露：多辖区差异化税包让脚投票替代投票。</li><li>效率条件：迁移成本低、拥挤成本可内部化、无跨区外部性。</li><li>资本化是实证抓手，房价溢价远超税差。</li><li>出处：Tiebout 1956；Oates「Fiscal Federalism」1972；Hamilton 1975。</li></ul>',6))])}const g=B(p,[["render",C]]);export{_ as __pageData,g as default};
